9	/**
10	 * Normalises the city of a newly built owner. The city is title-cased (each word
11	 * capitalised, remaining letters lower-cased) so that varied input casing is stored
12	 * consistently. However, if an owner already exists in the same city (compared
13	 * ignoring case and surrounding/repeated whitespace), that existing owner's exact
14	 * spelling of the city is reused instead, keeping a single canonical spelling per
15	 * city.
16	 */
17	public class NormaliseCity {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String city = owner.getCity();
21	        String key = DuplicateKey.normalize(city);
22	        if (key == null) {
23	            return;
24	        }
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (key.equals(DuplicateKey.normalize(existing.getCity()))) {
27	                owner.setCity(existing.getCity());
28	                return;
